"""Record chunk experiment even when exact-output comparator rejects it."""
import hashlib, json
from pathlib import Path
BASE=Path('/tmp/qwen38fn-prefill-20261022')
b,c=[json.loads((BASE/f'chunk-{n}.json').read_text()) for n in (1024,4096)]
assert b['protocol']==c['protocol'] and b['models']==c['models']
assert b['source_before']==b['source_after']==c['source_before']==c['source_after']
def key(row):return row['result']['id'],row['repetition'],row['arm']
bm={key(r):r for r in b['rows']};cm={key(r):r for r in c['rows']};assert bm.keys()==cm.keys()
pairs=[]
for k in bm:
 x,y=bm[k]['result'],cm[k]['result']
 assert x['prompt_token_accounting']==y['prompt_token_accounting']
 assert x['phase_metrics']['counts']==y['phase_metrics']['counts']
 assert x['speculative_used']==y['speculative_used']==(k[-1]=='mtp')
 xt,yt=[z['token_accounting']['choice_generated_token_ids'][0] for z in (x,y)]
 pairs.append({'id':k[0],'repetition':k[1],'arm':k[2], 'prompt_tokens':bm[k]['prompt_tokens'], 'ids_equal':xt==yt,'first_difference':next((i for i,(a,d) in enumerate(zip(xt,yt,strict=True)) if a!=d),None), 'before_ids':xt,'candidate_ids':yt,'before_phase':x['phase_metrics'],'candidate_phase':y['phase_metrics'],'before_acceptance':x['acceptance'],'candidate_acceptance':y['acceptance']})
summary={}
for length in (1024,4096):
 for arm in ('ar','mtp'):
  data=[p for p in pairs if p['prompt_tokens']==length and p['arm']==arm and p['repetition']>=0]
  rates={}
  for side in ('before','candidate'):
   phases=[p[side+'_phase'] for p in data]
   rates[side]={name:1000*sum(p['counts'][count] for p in phases)/sum(p['times_ms'][clock] for p in phases) for name,count,clock in (('prefill_tok_s','new_prompt_tokens','prefill_wall_ms'),('decode_tok_s','decode_transitions','decode_wall_ms'))}
  rates['percent_change']={n:100*(rates['candidate'][n]/rates['before'][n]-1) for n in rates['before']}
  summary[f'{length}:{arm}']=rates
repeat=[]
for d in (b,c):
 groups={}
 for r in d['rows']:groups.setdefault((r['result']['id'],r['arm']),[]).append(r['result']['token_accounting'])
 repeat.append(all(all(v==values[0] for v in values) for values in groups.values()))
report={'status':'exact_comparison_failed_pending_production_review','command':b['command'],'protocol':b['protocol'],'source':b['source_before'],'models':b['models'],'host_before':b['host_before'],'host_candidate':c['host_before'],'overrides':{'before':1024,'candidate':4096},'repeat_output_equal':repeat,'checks':{'prompt_hashes_equal':True,'counts_equal':True,'routes_correct':True,'outputs_equal':all(p['ids_equal'] for p in pairs)},'summary':summary,'pairs':pairs,'raw':{str(BASE/f'chunk-{n}.json'):hashlib.sha256((BASE/f'chunk-{n}.json').read_bytes()).hexdigest() for n in (1024,4096)},'limitations':['Timings are experimental, not a production-correctness or promotion verdict.','Decode paths process different generated trajectories where output IDs differ.','Readiness endpoint captured startup slices, not live request slices; separate live telemetry is required.']}
(BASE/'chunk-diagnostic.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'checks':report['checks'],'repeats':repeat,'summary':summary},indent=2))

