"""Aligned strict-teacher diagnostic for idle chunk sizes; not full promotion."""
from pathlib import Path
from types import SimpleNamespace
import hashlib, json, os, time
import numpy as np
from hipengine import LLM
from hipengine.execution_profiles import ExecutionProfile, resolve_runtime_profile
from hipengine.generation.qwen4_exp_profiles import _strict_binder, QWEN4_EXP_MODEL
from hipengine.runtime.moe_graph import MoeGraphCache
from hipengine.benchmark.execution_profiles import RowDescriptor, compare_profile_logits
from scripts.qwen4exp_canonical_ar_bench import _git_metadata, _host_metadata, sha256_path

OUT=Path('/tmp/qwen38fn-prefill-20261022/chunk-numerics'); OUT.mkdir(exist_ok=True)
MODEL='/models/gguf/unsloth-Qwen3.8-Flash-Next-UD-Q4_K_XL/UD-Q4_K_XL'
cases=json.loads(Path('benchmarks/fixtures/qwen4exp_canonical_ar_p512_p1024_p4096.json').read_text())['cases']
cases=[c for c in cases if c['prompt_tokens']==4096]
report={'status':'running','source':_git_metadata(Path.cwd()),'host':_host_metadata(), 'driver_sha256':sha256_path(Path(__file__)), 'protocol':{'lengths':[2053,4096],'categories':4,'decode_steps':24,'candidate_repeats':2,'full_promotion_gate':False},'cases':[]}
if (OUT/'result.json').exists():
 prior=json.loads((OUT/'result.json').read_text())
 assert prior['source']['head']==report['source']['head'] and report['source']['tracked_clean']
 report['cases']=prior['cases']
 report['recovery']={'reason':'ENOSPC during third capture','prior_driver_sha256':prior['driver_sha256'],'completed_cases_preserved':len(prior['cases'])}
 for row in report['cases']:
  with np.load(OUT/(row['id']+'.npz')) as archive:
   for key in archive.files: assert np.isfinite(archive[key]).all()
completed={row['id'] for row in report['cases']}
def save(): (OUT/'result.json').write_text(json.dumps(report,indent=2,default=str)+'\n')
llm=LLM(MODEL,backend='hip_gfx1151',quant='gguf_ud_q4_k_xl',execution_profile='production',max_sequence_length=8192,max_active_requests=1,prefix_cache='off',kv_storage='bf16')
g=llm._get_text_generator();g=getattr(g,'_inner',g);r=g.runner
assert r.prefill_chunk_size==4096
prod={k:v for k,v in os.environ.items() if k.startswith('HIPENGINE_')}
strict=resolve_runtime_profile(model=QWEN4_EXP_MODEL,backend='hip_gfx1151',quant='gguf_ud_q4_k_xl',profile=ExecutionProfile.STRICT)
_strict_binder(SimpleNamespace(),strict)
envs={'strict':{k:v for k,v in os.environ.items() if k.startswith('HIPENGINE_')},'production':prod}
report['environments']=envs
caches={'production':(r.moe_graph_cache,r.layer_graph_cache)}
caches['strict']=tuple(MoeGraphCache(r.runtime,enabled=c.enabled) for c in caches['production'])
def select(profile,chunk):
 for k in tuple(os.environ):
  if k.startswith('HIPENGINE_'):os.environ.pop(k)
 os.environ.update(envs[profile]);r.moe_graph_cache,r.layer_graph_cache=caches[profile];r.prefill_chunk_size=chunk

def capture(profile,chunk,prompt,forced=None):
 select(profile,chunk);r.reset();first=r.prefill(prompt)
 logits=[np.array(first.logits,dtype=np.float32,copy=True)];tokens=[int(first.token_id)]
 for i in range(24):
  result=r.step(tokens[-1] if forced is None else int(forced[i]))
  logits.append(np.array(result.logits,dtype=np.float32,copy=True));tokens.append(int(result.token_id))
 assert r.position==len(prompt)+24
 assert all(np.isfinite(a).all() for a in logits)
 return np.stack(logits),np.array(tokens)
try:
 for length in (2053,4096):
  for case in cases:
   name=case['id']+'-length'+str(length);prompt=case['prompt_token_ids'][:length]
   if name in completed:
    print('PRESERVED',name,flush=True);continue
   teacher,tokens=capture('strict',1024,prompt)
   baseline,bt=capture('production',1024,prompt,tokens)
   candidate,ct=capture('production',4096,prompt,tokens)
   repeat,rt=capture('production',4096,prompt,tokens)
   np.savez_compressed(OUT/(name+'.npz'),teacher=teacher,baseline=baseline,candidate=candidate,tokens=tokens,baseline_tokens=bt,candidate_tokens=ct)
   desc=[RowDescriptor(name,i,name,i,case['category'],str(length),'prefill' if i==0 else 'decode',int(tokens[i])) for i in range(25)]
   row={'id':name,'prompt_sha256':hashlib.sha256(np.asarray(prompt,dtype=np.int64).tobytes()).hexdigest(),'length':length,'category':case['category'],'repeat_equal':bool(np.array_equal(candidate,repeat) and np.array_equal(ct,rt)),'baseline_vs_strict':compare_profile_logits(teacher,baseline,desc),'candidate_vs_strict':compare_profile_logits(teacher,candidate,desc),'candidate_vs_baseline_diagnostic':compare_profile_logits(baseline,candidate,desc)}
   report['cases'].append(row);save()
   print(name,'repeat',row['repeat_equal'],{key:(row[key]['hard_gates_passed'],row[key]['summary']) for key in ('baseline_vs_strict','candidate_vs_strict')},flush=True)
 report['status']='diagnostic_complete';save()
finally:
 select('production',4096)
 for cache in caches['strict']:cache.close()
 llm.close();save()
